Propuesta de script manual read-only:

`/openclaw/workspace/main/dashboard-v2/tools/generate-tokens-daily-summary.js`

## Qué haría

- Leer solo:
  - `~/.openclaw/agents/main/sessions/*.jsonl`
- Parsear cada línea JSONL.
- Usar solo entradas con:
  - `timestamp` válido;
  - `usage.totalTokens > 0`.
- Excluir del consumo:
  - `totalTokens = 0`;
  - entradas sin `usage`;
  - JSON inválido;
  - timestamps inválidos.
- Agrupar por día local en `Europe/Madrid`.
- Sumar:
  - `usage.totalTokens`;
  - `usage.input`;
  - `usage.output`;
  - `usage.cacheRead`;
  - `usage.cacheWrite`;
  - `usage.cost.total`.
- Conservar calidad:
  - entradas totales;
  - válidas;
  - cero tokens;
  - sin usage;
  - JSON inválidas;
  - timestamp inválido.
- Escribir snapshot en:
  - `dashboard-v2/snapshots/tokens-daily-summary.json`

## Script propuesto

```js
#!/usr/bin/env node
import fs from "node:fs";
import path from "node:path";
import os from "node:os";
import readline from "node:readline";

const TIMEZONE = "Europe/Madrid";
const SOURCE_DIR = path.join(os.homedir(), ".openclaw", "agents", "main", "sessions");
const OUTPUT_FILE = "/openclaw/workspace/main/dashboard-v2/snapshots/tokens-daily-summary.json";

function isNumber(value) {
  return typeof value === "number" && Number.isFinite(value);
}

function addNullableNumber(target, key, value, presenceKey) {
  if (isNumber(value)) {
    target[key] += value;
    target[presenceKey] += 1;
  }
}

function localDay(timestamp) {
  const date = new Date(timestamp);
  if (Number.isNaN(date.getTime())) return null;

  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone: TIMEZONE,
    year: "numeric",
    month: "2-digit",
    day: "2-digit"
  }).formatToParts(date);

  const y = parts.find(p => p.type === "year")?.value;
  const m = parts.find(p => p.type === "month")?.value;
  const d = parts.find(p => p.type === "day")?.value;

  return y && m && d ? `${y}-${m}-${d}` : null;
}

function emptyDay(date) {
  return {
    date,
    agent: "main",
    status: "real",
    source: SOURCE_DIR,
    timezone: TIMEZONE,
    metrics: {
      totalTokens: 0,
      costTotal: null,
      usageEntries: 0
    },
    breakdown: {
      input: 0,
      output: 0,
      cacheRead: 0,
      cacheWrite: 0
    },
    fieldPresence: {
      input: 0,
      output: 0,
      cacheRead: 0,
      cacheWrite: 0,
      costTotal: 0
    },
    quality: {
      entries_total: 0,
      entries_valid_usage: 0,
      entries_zero_total_tokens: 0,
      entries_missing_usage: 0,
      entries_invalid_json: 0,
      entries_invalid_timestamp: 0
    },
    models_seen: [],
    providers_seen: []
  };
}

function addUnique(list, value) {
  if (typeof value === "string" && value && !list.includes(value)) {
    list.push(value);
  }
}

async function main() {
  const qualityGlobal = {
    files_read: 0,
    entries_total: 0,
    entries_valid_usage: 0,
    entries_zero_total_tokens: 0,
    entries_missing_usage: 0,
    entries_invalid_json: 0,
    entries_invalid_timestamp: 0
  };

  const days = new Map();

  if (!fs.existsSync(SOURCE_DIR)) {
    const snapshot = {
      schema: "neodaemon.tokens_daily_summary.v1",
      status: "no_disponible",
      generated_at: new Date().toISOString(),
      timezone: TIMEZONE,
      source: SOURCE_DIR,
      output: OUTPUT_FILE,
      agent: "main",
      days: [],
      quality: qualityGlobal,
      limitations: [
        "Source directory does not exist.",
        "No token values were inferred.",
        "Dashboard was not modified."
      ]
    };

    fs.writeFileSync(OUTPUT_FILE, JSON.stringify(snapshot, null, 2) + "\n");
    return;
  }

  const files = fs.readdirSync(SOURCE_DIR)
    .filter(name => name.endsWith(".jsonl"))
    .map(name => path.join(SOURCE_DIR, name))
    .sort();

  for (const file of files) {
    qualityGlobal.files_read += 1;

    const stream = fs.createReadStream(file, { encoding: "utf8" });
    const rl = readline.createInterface({ input: stream, crlfDelay: Infinity });

    for await (const line of rl) {
      if (!line.trim()) continue;

      qualityGlobal.entries_total += 1;

      let entry;
      try {
        entry = JSON.parse(line);
      } catch {
        qualityGlobal.entries_invalid_json += 1;
        continue;
      }

      const day = localDay(entry.timestamp);
      if (!day) {
        qualityGlobal.entries_invalid_timestamp += 1;
        continue;
      }

      if (!days.has(day)) days.set(day, emptyDay(day));
      const dayBucket = days.get(day);
      dayBucket.quality.entries_total += 1;

      const usage = entry.usage;
      if (!usage || typeof usage !== "object") {
        qualityGlobal.entries_missing_usage += 1;
        dayBucket.quality.entries_missing_usage += 1;
        continue;
      }

      if (!isNumber(usage.totalTokens) || usage.totalTokens === 0) {
        qualityGlobal.entries_zero_total_tokens += 1;
        dayBucket.quality.entries_zero_total_tokens += 1;
        continue;
      }

      if (usage.totalTokens < 0) {
        qualityGlobal.entries_zero_total_tokens += 1;
        dayBucket.quality.entries_zero_total_tokens += 1;
        continue;
      }

      qualityGlobal.entries_valid_usage += 1;
      dayBucket.quality.entries_valid_usage += 1;

      dayBucket.metrics.totalTokens += usage.totalTokens;
      dayBucket.metrics.usageEntries += 1;

      addNullableNumber(dayBucket.breakdown, "input", usage.input, "input");
      addNullableNumber(dayBucket.breakdown, "output", usage.output, "output");
      addNullableNumber(dayBucket.breakdown, "cacheRead", usage.cacheRead, "cacheRead");
      addNullableNumber(dayBucket.breakdown, "cacheWrite", usage.cacheWrite, "cacheWrite");

      if (usage.cost && isNumber(usage.cost.total)) {
        dayBucket.metrics.costTotal =
          dayBucket.metrics.costTotal === null
            ? usage.cost.total
            : dayBucket.metrics.costTotal + usage.cost.total;
        dayBucket.fieldPresence.costTotal += 1;
      }

      addUnique(dayBucket.models_seen, entry.model);
      addUnique(dayBucket.providers_seen, entry.provider);
    }
  }

  const snapshot = {
    schema: "neodaemon.tokens_daily_summary.v1",
    status: "real",
    generated_at: new Date().toISOString(),
    timezone: TIMEZONE,
    source: SOURCE_DIR,
    output: OUTPUT_FILE,
    agent: "main",
    rules: {
      valid_usage: "usage.totalTokens > 0 with valid timestamp",
      zero_total_tokens: "excluded from consumption totals and counted in quality",
      grouping: "local day in Europe/Madrid",
      cost: "sum usage.cost.total only when present; null when unavailable"
    },
    days: [...days.values()].sort((a, b) => a.date.localeCompare(b.date)),
    quality: qualityGlobal,
    limitations: [
      "Reads only main agent sessions.",
      "Does not include task-validator sessions.",
      "Usage entries are model/provider log entries, not necessarily human Telegram messages.",
      "totalTokens semantics depend on OpenClaw/provider logging.",
      "cacheRead/cacheWrite are preserved separately.",
      "Entries with totalTokens = 0 are excluded from consumption totals.",
      "Dashboard is not modified by this script."
    ]
  };

  fs.mkdirSync(path.dirname(OUTPUT_FILE), { recursive: true });
  fs.writeFileSync(OUTPUT_FILE, JSON.stringify(snapshot, null, 2) + "\n");
}

main().catch(error => {
  console.error(error);
  process.exit(1);
});
```

## Riesgos

1. **“usageEntries” no son mensajes humanos**
   - Son entradas de uso en sesiones JSONL.
   - Mejor no llamarlas “mensajes” en UI final.

2. **`totalTokens` puede tener semántica de proveedor**
   - Puede incluir o no ciertos componentes.
   - Por eso cache se conserva separado.

3. **Coste no siempre fiable/comparable**
   - `usage.cost.total` se suma solo si existe.
   - No se calcula coste propio.

4. **Solo cubre `main`**
   - No incluye `task-validator`.
   - Si se añade luego, debe ir separado.

5. **`totalTokens = 0`**
   - Se excluye del consumo.
   - Se conserva en `quality`.

6. **Privacidad/localidad**
   - Lee logs locales de sesiones.
   - No envía nada fuera.
   - Pero el snapshot resultante puede revelar volumen de uso/coste, así que debe quedarse local.

## Recomendación

Me parece seguro como siguiente paso si lo dejamos en:

- script manual;
- read-only sobre sesiones;
- snapshot local;
- sin dashboard;
- sin cron;
- sin automatización.

